/**
 * Central Mock Registry for External Service Integration Tests
 * 
 * This registry provides centralized, consistent mocks for all external services
 * to ensure reliable, fast test execution without external dependencies.
 */

import { jest } from '@jest/globals';
import type { ChatCompletion, Embedding } from 'openai/resources';

// ============================================
// OpenAI Mock Configuration
// ============================================

export interface OpenAIMockConfig {
  embeddings?: {
    response?: number[];
    error?: Error;
  };
  chat?: {
    response?: string;
    error?: Error;
  };
}

/**
 * Creates a properly mocked OpenAI client with Jest functions
 */
export function createMockOpenAI(config: OpenAIMockConfig = {}) {
  const defaultEmbedding = config.embeddings?.response || Array(1536).fill(0).map(() => Math.random());
  const defaultChatResponse = config.chat?.response || 'Mocked AI response';

  const mockOpenAI = {
    embeddings: {
      create: jest.fn().mockImplementation(async (params: any) => {
        if (config.embeddings?.error) {
          throw config.embeddings.error;
        }
        
        const embeddings = Array.isArray(params.input) 
          ? params.input.map((_, index) => ({
              object: 'embedding' as const,
              embedding: defaultEmbedding,
              index
            }))
          : [{
              object: 'embedding' as const,
              embedding: defaultEmbedding,
              index: 0
            }];
        
        return {
          object: 'list' as const,
          data: embeddings,
          model: params.model || 'text-embedding-ada-002',
          usage: {
            prompt_tokens: 8,
            total_tokens: 8
          }
        };
      })
    },
    chat: {
      completions: {
        create: jest.fn().mockImplementation(async (params: any) => {
          if (config.chat?.error) {
            throw config.chat.error;
          }
          
          return {
            id: 'chatcmpl-test123',
            object: 'chat.completion' as const,
            created: Date.now(),
            model: params.model || 'gpt-4',
            usage: {
              prompt_tokens: 10,
              completion_tokens: 20,
              total_tokens: 30
            },
            choices: [{
              index: 0,
              message: {
                role: 'assistant' as const,
                content: defaultChatResponse
              },
              finish_reason: 'stop' as const
            }]
          } satisfies ChatCompletion;
        })
      }
    }
  };

  return mockOpenAI;
}

// ============================================
// Fetch/HTTP Mock Configuration
// ============================================

export interface FetchMockConfig {
  responses?: Map<string, { status: number; data: any }>;
  defaultResponse?: { status: number; data: any };
  error?: Error;
}

/**
 * Creates a mock fetch function for HTTP requests
 */
export function createMockFetch(config: FetchMockConfig = {}) {
  const defaultResponse = config.defaultResponse || { status: 200, data: { success: true } };
  
  return jest.fn().mockImplementation(async (url: string, options?: any) => {
    if (config.error) {
      throw config.error;
    }

    const response = config.responses?.get(url) || defaultResponse;
    
    return {
      ok: response.status >= 200 && response.status < 300,
      status: response.status,
      statusText: response.status === 200 ? 'OK' : 'Error',
      headers: new Headers({ 'content-type': 'application/json' }),
      json: async () => response.data,
      text: async () => JSON.stringify(response.data),
      blob: async () => new Blob([JSON.stringify(response.data)]),
      arrayBuffer: async () => new ArrayBuffer(0),
      formData: async () => new FormData(),
      clone: () => ({ json: async () => response.data })
    };
  });
}

// ============================================
// Database/Prisma Mock Configuration
// ============================================

export interface PrismaMockConfig {
  models?: {
    [key: string]: {
      findMany?: any[];
      findUnique?: any;
      findFirst?: any;
      create?: any;
      update?: any;
      delete?: any;
      count?: number;
    };
  };
}

/**
 * Creates a mock Prisma client with common operations
 */
export function createMockPrisma(config: PrismaMockConfig = {}) {
  const createModelMock = (modelName: string) => {
    const modelConfig = config.models?.[modelName] || {};
    
    return {
      findMany: jest.fn().mockResolvedValue(modelConfig.findMany || []),
      findUnique: jest.fn().mockResolvedValue(modelConfig.findUnique || null),
      findFirst: jest.fn().mockResolvedValue(modelConfig.findFirst || null),
      create: jest.fn().mockResolvedValue(modelConfig.create || { id: 'mock-id', createdAt: new Date() }),
      createMany: jest.fn().mockResolvedValue({ count: 1 }),
      update: jest.fn().mockResolvedValue(modelConfig.update || { id: 'mock-id', updatedAt: new Date() }),
      updateMany: jest.fn().mockResolvedValue({ count: 1 }),
      delete: jest.fn().mockResolvedValue(modelConfig.delete || { id: 'mock-id' }),
      deleteMany: jest.fn().mockResolvedValue({ count: 1 }),
      count: jest.fn().mockResolvedValue(modelConfig.count || 0),
      aggregate: jest.fn().mockResolvedValue({ _count: 0 }),
      groupBy: jest.fn().mockResolvedValue([])
    };
  };

  return {
    user: createModelMock('user'),
    team: createModelMock('team'),
    student: createModelMock('student'),
    curriculumExpectation: createModelMock('curriculumExpectation'),
    oerResource: createModelMock('oerResource'),
    lessonPlan: createModelMock('lessonPlan'),
    unitPlan: createModelMock('unitPlan'),
    newsletter: createModelMock('newsletter'),
    progressCheck: createModelMock('progressCheck'),
    embeddingCache: createModelMock('embeddingCache'),
    $connect: jest.fn().mockResolvedValue(undefined),
    $disconnect: jest.fn().mockResolvedValue(undefined),
    $transaction: jest.fn().mockImplementation(async (fn) => {
      if (typeof fn === 'function') {
        return fn({
          user: createModelMock('user'),
          team: createModelMock('team'),
          student: createModelMock('student'),
          curriculumExpectation: createModelMock('curriculumExpectation'),
          oerResource: createModelMock('oerResource'),
          lessonPlan: createModelMock('lessonPlan'),
          unitPlan: createModelMock('unitPlan'),
          newsletter: createModelMock('newsletter'),
          progressCheck: createModelMock('progressCheck'),
          embeddingCache: createModelMock('embeddingCache')
        });
      }
      return Promise.all(fn);
    })
  };
}

// ============================================
// Mock Registry Setup Functions
// ============================================

/**
 * Sets up all mocks with proper Jest module mocking
 */
export function setupMockRegistry() {
  // Mock OpenAI
  jest.mock('openai', () => ({
    default: jest.fn().mockImplementation(() => createMockOpenAI())
  }));

  // Mock node-fetch
  jest.mock('node-fetch', () => ({
    default: createMockFetch(),
    Response: jest.fn(),
    Headers: jest.fn(),
    Request: jest.fn()
  }));

  // Mock Prisma
  jest.mock('@prisma/client', () => ({
    PrismaClient: jest.fn().mockImplementation(() => createMockPrisma())
  }));

  // Mock database package
  jest.mock('@teaching-engine/database', () => ({
    prisma: createMockPrisma(),
    Prisma: {
      PrismaClientKnownRequestError: class PrismaClientKnownRequestError extends Error {
        code: string;
        constructor(message: string, { code }: { code: string }) {
          super(message);
          this.code = code;
        }
      }
    }
  }));
}

/**
 * Cleans up all mocks after tests
 */
export function cleanupMockRegistry() {
  jest.clearAllMocks();
  jest.resetModules();
}

